"""The web package's Tailwind tokens (web/src/styles/tokens.css, generated by
web/scripts/tokens.mjs) must match docs/design/tokens.json, so a change to renderer/tokens.py
fails here until `npm run tokens` is run in web/ (D28)."""

from __future__ import annotations

import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TOKENS = json.loads((ROOT / "docs/design/tokens.json").read_text(encoding="utf-8"))
CSS = (ROOT / "web/src/styles/tokens.css").read_text(encoding="utf-8")


def declarations(block: str) -> dict[str, str]:
    return dict(re.findall(r"(--[\w*-]+):\s*([^;]+);", block))


def block(pattern: str) -> dict[str, str]:
    match = re.search(pattern, CSS, re.S)
    assert match, f"block {pattern!r} missing from tokens.css"
    return declarations(match.group(1))


def test_palettes_match_both_themes():
    light = block(r"\n:root \{(.*?)\n\}")
    dark_media = block(r"prefers-color-scheme: dark\) \{\s*:root:not\(\[data-theme=\"light\"\]\) \{(.*?)\}")
    dark_attr = block(r":root\[data-theme=\"dark\"\] \{(.*?)\}")
    for name, value in TOKENS["themes"]["light"].items():
        assert light[f"--pn-{name}"] == value, name
    for name, value in TOKENS["themes"]["dark"].items():
        assert dark_media[f"--pn-{name}"] == value, name
        assert dark_attr[f"--pn-{name}"] == value, name


def test_tailwind_theme_matches_tokens():
    theme = block(r"@theme \{(.*?)\n\}")
    for name, value in TOKENS["colors"].items():
        assert theme[f"--color-{name}"] == value, name
    # Font stacks reach the page through Astro's Fonts API (web/astro.config.ts reads them from
    # tokens.json); the theme points at the variables it emits.
    for name in TOKENS["fontFamily"]:
        assert theme[f"--font-{name}"] == f"var(--pn-font-{name})", name
    for name, (size, opts) in TOKENS["fontSize"].items():
        assert theme[f"--text-{name}"] == size, name
        assert theme[f"--text-{name}--line-height"] == opts["lineHeight"], name
        assert theme[f"--text-{name}--letter-spacing"] == opts["letterSpacing"], name
        assert theme[f"--text-{name}--font-weight"] == opts["fontWeight"], name
    for name, value in TOKENS["spacing"].items():
        assert theme[f"--spacing-{name}"] == value, name
    for name, value in TOKENS["borderRadius"].items():
        assert theme[f"--radius-{name}"] == value, name
    for name, value in TOKENS["boxShadow"].items():
        assert theme[f"--shadow-{name}"] == value, name
    # No Tailwind default colour, font, size, radius or shadow leaks through (spec #1, Website).
    for namespace in ("color", "font", "text", "radius", "shadow"):
        assert theme[f"--{namespace}-*"] == "initial", namespace
